UPDATE t_article
title = #{title}, summary = #{summary}, content = #{content}, cover_image = #{coverImage}, category_id = #{categoryId}, status = #{status}, update_time = #{updateTime}
WHERE id = #{id}

UPDATE t_article SET comment_count = CASE WHEN comment_count > 0
                                          THEN comment_count - 1 ELSE 0 END
WHERE id = #{id}
